+        int[] lps = new int[pattern.length()];
+        int prefixLength = 0;
+
+        for (int i = 1; i < pattern.length();) {
+            if (pattern.charAt(i) == pattern.charAt(prefixLength)) {
+                lps[i++] = ++prefixLength;
+            } else if (prefixLength != 0) {
