+        int[] lps = buildLps(pat);
+        int textIndex = 0;
+        int patternIndex = 0;
+
+        while (textIndex < txt.length()) {
+            if (txt.charAt(textIndex) == pat.charAt(patternIndex)) {
+                textIndex++;
+                patternIndex++;
+
+                if (patternIndex == pat.length()) {
+                    matches.add(textIndex - patternIndex);
