+                }
+            } else if (patternIndex != 0) {
+                patternIndex = lps[patternIndex - 1];
+            } else {
+                textIndex++;
+            }
+        }
+
+        return matches;
+    }
+
+    private static void printMatches(List<Integer> matches) {
+        for (int i = 0; i < matches.size(); i++) {
+            if (i > 0) {
+                System.out.print(" ");
+            }
+            System.out.print(matches.get(i));
+        }
+        System.out.println();
